import { useState } from "react";

enum LoadState {
  Ready(message: string),
  Empty,
  Failed(message: string),
}

export const Status = () => {
  const [state] = useState<LoadState>(LoadState.Ready("Hello ttx"));

  return (
    <section data-state={match (state) {
      Ready => "ready",
      Empty => "empty",
      Failed => "failed",
    }}>
      {match (state) {
        Ready(message) => <strong>{message}</strong>,
        Empty => <span>Nothing here</span>,
        Failed(message) => <mark>{message}</mark>,
      }}
    </section>
  );
};

